<style>
.fi-main,.fi-page,.fi-ta-ctn,.fi-ta-content-ctn,.fi-ta-record,.fi-ta-record-content-ctn,.fi-ta-grid{min-width:0;max-width:100%}
.fi-ta-record{border-radius:20px;border:1px solid #e8e4d9;background:#fff;margin:0;box-shadow:0 3px 12px #30291704}
.fi-ta-content.fi-ta-content-grid{gap:14px!important;padding:16px!important;background:#f5f4ef}.fi-ta-record-content{padding:16px!important}.fi-ta-grid{gap:10px 14px!important}.fi-ta-record-content-ctn{display:flex!important;flex-direction:column!important;height:100%}.fi-ta-record-content-ctn>div:first-child{flex:1;min-width:0}.fi-ta-record .fi-ta-actions{padding:10px 16px!important;border-top:1px solid #eeebe3;background:#fbfaf7;border-radius:0 0 20px 20px}.fi-ta-record .fi-ta-text{font-size:13px}.fi-ta-text-item{white-space:normal;overflow-wrap:anywhere}.fi-ta-text-description{font-size:11px;color:#82765e;letter-spacing:.3px}.fi-ta-record .fi-ta-actions{flex-wrap:wrap;gap:8px}.fi-ta-header-toolbar{flex-wrap:wrap;gap:12px}.fi-ta-search-field{min-width:0;max-width:100%}
.fi-input-wrp{background:#fff;border:1px solid #d9d4c8;border-radius:14px;box-shadow:0 2px 5px #30291705;min-height:44px;transition:border-color .15s,box-shadow .15s}
.fi-input-wrp:focus-within{border-color:#a48647;box-shadow:0 0 0 3px #b18b361b}.fi-input-wrp.fi-invalid{border-color:#dc2626}.fi-input,.fi-select-input{min-height:42px;font-size:15px}.fi-input::placeholder{color:#999486}.fi-fo-field-label-content{font-weight:650;letter-spacing:.1px}.fi-input-wrp-prefix,.fi-input-wrp-suffix{color:#8a6c31}.fi-textarea{min-height:90px;padding:14px!important}
.lv-scanner{max-width:780px}.lv-camera{aspect-ratio:16/10;min-height:280px;border:1px solid #b9a16a;box-shadow:0 16px 35px #19191714;background:radial-gradient(ellipse at top,#444436,#191b17)}.lv-camera-reticle{inset:22% 14%;border-color:#e5c87c}.lv-camera-launch{position:absolute;inset:0;display:flex;flex-direction:column;gap:14px;align-items:center;justify-content:center;color:#f5e8c3;background:#19191755;cursor:pointer;z-index:2}.lv-camera-launch:focus-visible{outline:3px solid #e5c87c;outline-offset:-6px}.lv-camera-play{display:grid;place-items:center;width:72px;height:72px;border-radius:50%;background:#e2c477;color:#22251e;box-shadow:0 0 0 10px #e2c47714}.lv-camera-play svg{width:30px;height:30px}.lv-camera-launch strong{font-size:16px}.lv-camera-launch small{color:#e4dfd1}.lv-camera-actions{flex-wrap:wrap}.lv-camera-state{display:flex;justify-content:space-between;gap:10px;margin-bottom:12px;font-size:11px;font-weight:700;letter-spacing:1px;color:#847044}.lv-camera-state span:last-child{letter-spacing:0;color:#716f63}.lv-scanner .lv-muted{background:#f6f3eb;padding:12px 16px;border-radius:12px;color:#605844;margin-bottom:8px}
@media(max-width:640px){.fi-ta-content.fi-ta-content-grid{padding:10px!important;gap:10px!important}.fi-ta-record{margin:0}.fi-ta-record-content{padding:14px!important}.fi-ta-grid{gap:8px 12px!important}.fi-ta-record-content-ctn{flex-wrap:wrap}.fi-input,.fi-select-input{font-size:16px}.lv-camera{aspect-ratio:4/3;min-height:240px}.lv-camera-actions>.lv-button{flex:1}.fi-ta-header-toolbar>*{max-width:100%}.lv-camera-state{flex-wrap:wrap}}
.lv-space-photo{width:44px;height:44px;border-radius:12px;object-fit:cover;flex-shrink:0}.lv-record-photo{position:relative;width:100%;height:150px;border-radius:12px;overflow:hidden;background:#f3efe5}.lv-record-photo img{width:100%;height:100%;object-fit:cover;display:block}.lv-record-photo span{position:absolute;bottom:10px;right:10px;padding:4px 9px;border-radius:20px;background:#fffffff0;color:#66583d;font-size:10px;font-weight:650;letter-spacing:.5px}.lv-quick-form{min-width:0}.lv-quick-form .filepond--root{max-width:100%}.lv-scan-hint{font-size:12px;line-height:1.5;color:#77776d;margin:12px 0 0;text-align:center}.lv-camera-launch{padding:20px;text-align:center}.lv-scanner>small{display:block;line-height:1.6}
@media(max-width:640px){
.lv-quick-intro{gap:6px}.lv-quick-intro p{margin:0}.lv-quick-form .fi-sc-wizard.fi-contained .fi-sc-wizard-step.fi-active{padding:14px 12px!important}.lv-quick-form .fi-sc-wizard-header-step-btn{padding:14px!important;gap:12px!important}.lv-quick-form .fi-sc-wizard-footer{padding:0 12px 16px!important;gap:12px}.lv-quick-form .fi-sc-wizard-footer .fi-btn{min-height:46px}.lv-scanner{max-width:none;width:100%;min-width:0}.lv-camera{min-height:0;aspect-ratio:1.12;border-radius:18px}.lv-camera-reticle{inset:18% 9%}.lv-camera-launch{gap:16px;padding:18px}.lv-camera-play{width:60px;height:60px}.lv-camera-launch strong{font-size:14px;max-width:100%;line-height:1.5}.lv-camera-state{font-size:10px;gap:8px;letter-spacing:.6px;margin-bottom:12px}.lv-camera-actions{display:grid;grid-template-columns:1fr;margin-top:14px}.lv-camera-actions .lv-button{width:100%;min-height:48px}.lv-scanner .lv-muted{padding:12px;margin:14px 0 8px;line-height:1.6}.lv-scan-hint{margin-top:12px}.lv-record-photo{height:140px}
}
</style>
<style>
.lv-items-table .fi-ta-record-content{padding:12px!important}.lv-items-table .fi-ta-record .fi-ta-actions{padding:7px 12px!important}.lv-items-table .fi-ta-record{border-radius:16px;overflow:hidden}.lv-item-summary{display:flex;align-items:flex-start;gap:13px;min-width:0;text-align:left}.lv-item-thumb{width:88px;height:100px;flex:0 0 88px;border-radius:11px;object-fit:cover;background:#f3efe5}.lv-item-info{min-width:0;flex:1}.lv-item-info>strong{font-size:14px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.lv-item-path{font-size:11px;color:#7a766a;margin:4px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lv-item-metrics{display:flex;gap:12px;flex-wrap:wrap;align-items:baseline;font-size:12px;margin:7px 0}.lv-item-metrics b{font-weight:750}.lv-item-metrics small{font-size:9px;color:#857b66}.lv-item-metrics>span{color:#6d6a60}.lv-item-tags{display:flex;gap:5px;flex-wrap:wrap}.lv-item-tags span{font-size:9px;padding:3px 7px;border-radius:7px;background:#f3f0e8;color:#71603e;max-width:100%;overflow-wrap:anywhere}
.lv-browser{display:grid;grid-template-columns:245px minmax(0,1fr);gap:20px;align-items:start}.lv-location-tree{background:white;border:1px solid #e9e7df;border-radius:20px;padding:12px;position:sticky;top:85px;max-height:calc(100vh - 180px);overflow-y:auto}.lv-tree-heading{display:flex;justify-content:space-between;width:100%;padding:8px 7px 15px;font-size:13px}.lv-tree-row{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;text-align:left;font-size:12px;min-height:40px;padding:8px;border-radius:9px;transition:background .18s,color .18s;overflow-wrap:anywhere}.lv-tree-row:hover{background:#f6f3eb}.lv-tree-row.is-selected{background:#f1e8d2;color:#77591c;font-weight:750}.lv-tree-row small{font-size:10px;opacity:.7}.lv-tree-children{margin-left:12px;padding-left:7px;border-left:1px solid #e5dbc4;animation:lv-branch-in .2s ease-out}.lv-tree-help,.lv-tree-empty{font-size:11px;line-height:1.5;color:#8a8577;padding:10px 7px}.lv-browser-results{min-width:0}.lv-location-breadcrumb{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:12px;margin:0 0 16px}.lv-location-breadcrumb button{color:#886a2f}.lv-location-breadcrumb strong{font-weight:700}.lv-browser-loading{font-size:11px;color:#886a2f;margin-bottom:10px}
@keyframes lv-branch-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
@supports(animation-timeline:view()){@media(prefers-reduced-motion:no-preference){.lv-items-table .fi-ta-record{animation:lv-branch-in linear both;animation-timeline:view();animation-range:entry 0% entry 15%}}}
@media(max-width:767px){.lv-browser{grid-template-columns:minmax(0,1fr);gap:14px}.lv-location-tree{position:static;max-height:320px;padding:10px 12px}.lv-tree-heading{padding-bottom:10px}.lv-tree-help{margin:0;padding-bottom:3px}.lv-location-breadcrumb{font-size:11px;margin-bottom:12px}.lv-items-table .fi-ta-content.fi-ta-content-grid{padding:8px!important;gap:8px!important}.lv-item-thumb{width:76px;height:90px;flex-basis:76px}.lv-item-summary{gap:11px}.lv-item-info>strong{font-size:13px}.lv-item-metrics{margin:5px 0}.lv-items-table .fi-ta-record .fi-ta-actions .fi-link{min-height:30px}.fi-sc-tabs-tab{white-space:normal}.fi-sc-tabs-tab-content{min-width:0}}
@media(prefers-reduced-motion:reduce){.lv-tree-children,.lv-items-table .fi-ta-record{animation:none!important}.lv-tree-row{transition:none}}
</style>

<style>@media(max-width:640px){.lv-item-editor .fi-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;overflow:visible;padding:8px}.lv-item-editor .fi-tabs-item{min-width:0;white-space:normal;font-size:11px;padding:9px 5px;line-height:1.4}.lv-item-editor .fi-tabs-item>.fi-icon{display:none}}</style>
